enum TurnState {
  idle('idle'),
  running('running'),
  /// Waiting for a model slot.
  waiting('waiting'),
  /// Blocked on a recipe approval.
  awaitingApproval('awaiting_approval');

  const TurnState(this.wire);
  final String wire;

  static TurnState fromJson(Object? json) =>
      values.firstWhere((v) => v.wire == json, orElse: () => throw FormatException('unknown TurnState: $json'));

  String toJson() => wire;
}

/// `POST /api/web-session`: a new browser session of the caller's kind, for a client that sets
/// the workspace's cookie itself (the desktop's panes, the phone's webviews) instead of putting a
/// token in a cookie or a URL.
class WebSession {
  const WebSession({
    required this.cookieName,
    required this.value,
    required this.path,
  });

  /// The cookie's name.
  final String cookieName;

  /// The session secret (`ses_...`): the cookie's value.
  final String value;

  /// The cookie's `Path` (the workspace's routes).
  final String path;

  factory WebSession.fromJson(Map<String, Object?> json) => WebSession(
        cookieName: json['cookie_name'] as String,
        value: json['value'] as String,
        path: json['path'] as String,
      );

  Map<String, Object?> toJson() => {
        'cookie_name': cookieName,
        'value': value,
        'path': path,
      };
}

enum WorkerState {
  starting('starting'),
  running('running'),
  done('done'),
  failed('failed'),
  /// Stopped before finishing, to be resumed later (a usage limit was hit).
  paused('paused'),
  /// Reached its turn limit (tokens, or Claude Code's turns) without finishing; waits for its orchestrator to continue or stop it.
  stuck('stuck');

  const WorkerState(this.wire);
  final String wire;

  static WorkerState fromJson(Object? json) =>
      values.firstWhere((v) => v.wire == json, orElse: () => throw FormatException('unknown WorkerState: $json'));

  String toJson() => wire;
}
